import React, { useState, useEffect } from 'react';
import { X, Download, ZoomIn } from 'lucide-react';

const MediaMessage = ({ message, isOwn }) => {
  const [showFullscreen, setShowFullscreen] = useState(false);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [imageError, setImageError] = useState(false);

  const { media_url, media_type, content } = message;

  // Handle ESC key to close fullscreen
  useEffect(() => {
    const handleEscape = (e) => {
      if (e.key === 'Escape' && showFullscreen) {
        setShowFullscreen(false);
      }
    };

    if (showFullscreen) {
      document.addEventListener('keydown', handleEscape);
      // Prevent body scroll when fullscreen is open
      document.body.style.overflow = 'hidden';
    }

    return () => {
      document.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = 'unset';
    };
  }, [showFullscreen]);

  // Download media
  const handleDownload = async (e) => {
    e.stopPropagation();
    try {
      const response = await fetch(media_url);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `3dmatch-media-${Date.now()}.${media_type === 'image' ? 'jpg' : 'mp4'}`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Error downloading media:', error);
      alert('Error downloading media. Please try again.');
    }
  };

  // Handle image click to open fullscreen
  const handleImageClick = (e) => {
    e.stopPropagation();
    if (!imageError && imageLoaded) {
      setShowFullscreen(true);
    }
  };

  // Handle image load error
  const handleImageError = () => {
    setImageError(true);
    console.error('Error loading image:', media_url);
  };

  return (
    <>
      <div className={`media-message ${isOwn ? 'own' : 'other'}`}>
        {/* Image */}
        {media_type === 'image' && (
          <div 
            className="media-message-image-wrapper"
            onClick={handleImageClick}
          >
            {!imageLoaded && !imageError && (
              <div className="media-message-loading">
                <div className="spinner"></div>
              </div>
            )}
            {imageError ? (
              <div className="media-message-error">
                <X size={32} />
                <p>Error loading image</p>
              </div>
            ) : (
              <>
                <img
                  src={media_url}
                  alt="Sent media"
                  className="media-message-image"
                  onLoad={() => setImageLoaded(true)}
                  onError={handleImageError}
                  style={{ display: imageLoaded ? 'block' : 'none' }}
                />
                {imageLoaded && (
                  <div className="media-message-overlay">
                    <button
                      className="media-action-btn"
                      onClick={handleDownload}
                      title="Download"
                    >
                      <Download size={18} />
                    </button>
                    <button
                      className="media-action-btn"
                      title="View fullscreen"
                    >
                      <ZoomIn size={18} />
                    </button>
                  </div>
                )}
              </>
            )}
          </div>
        )}

        {/* Video */}
        {media_type === 'video' && (
          <div className="media-message-video-wrapper">
            <video 
              src={media_url}
              controls
              className="media-message-video"
              preload="metadata"
              onError={() => console.error('Error loading video:', media_url)}
            />
            <button
              className="media-download-btn"
              onClick={handleDownload}
              title="Download video"
            >
              <Download size={16} />
            </button>
          </div>
        )}

        {/* Caption */}
        {content && (
          <div className="media-message-caption">
            {content}
          </div>
        )}
      </div>

      {/* Fullscreen Image Viewer */}
      {showFullscreen && media_type === 'image' && !imageError && (
        <div 
          className="media-fullscreen-overlay"
          onClick={() => setShowFullscreen(false)}
        >
          <div className="media-fullscreen-header">
            <button
              className="media-fullscreen-close"
              onClick={() => setShowFullscreen(false)}
              title="Close (ESC)"
            >
              <X size={28} />
            </button>
            <button
              className="media-fullscreen-download"
              onClick={handleDownload}
              title="Download image"
            >
              <Download size={24} />
            </button>
          </div>
          <div className="media-fullscreen-content">
            <img
              src={media_url}
              alt="Fullscreen view"
              onClick={(e) => e.stopPropagation()}
            />
          </div>
          {content && (
            <div className="media-fullscreen-caption">
              {content}
            </div>
          )}
          <div className="media-fullscreen-hint">
            Press ESC or click outside to close
          </div>
        </div>
      )}
    </>
  );
};

export default MediaMessage;