import React, { useState, useRef } from 'react';
import { X, Image, Video, FileText, Loader } from 'lucide-react';
import { supabase } from '../../supabaseClient';

const MediaUpload = ({ onMediaSelected, onClose }) => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [caption, setCaption] = useState('');
  const fileInputRef = useRef(null);

  // Handle file selection
  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Validate file type
    const validImageTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];
    const validVideoTypes = ['video/mp4', 'video/webm', 'video/ogg', 'video/quicktime'];
    
    if (!validImageTypes.includes(file.type) && !validVideoTypes.includes(file.type)) {
      alert('Please select an image (JPG, PNG, GIF) or video (MP4, WebM)');
      return;
    }

    // Validate file size (max 50MB)
    const maxSize = 50 * 1024 * 1024; // 50MB
    if (file.size > maxSize) {
      alert('File too large. Maximum size: 50MB');
      return;
    }

    setSelectedFile(file);

    // Create preview
    const reader = new FileReader();
    reader.onloadend = () => {
      setPreview(reader.result);
    };
    reader.readAsDataURL(file);
  };

  // Upload file to Supabase Storage
  const uploadMedia = async () => {
    if (!selectedFile) return null;

    setUploading(true);

    try {
      const fileExt = selectedFile.name.split('.').pop();
      const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
      const filePath = `${fileName}`;

      // Upload to Supabase Storage
      const { error: uploadError } = await supabase.storage
        .from('message-media')
        .upload(filePath, selectedFile, {
          cacheControl: '3600',
          upsert: false
        });

      if (uploadError) throw uploadError;

      // Get public URL
      const { data: urlData } = supabase.storage
        .from('message-media')
        .getPublicUrl(filePath);

      const mediaUrl = urlData.publicUrl;
      
      // Determine media type
      const mediaType = selectedFile.type.startsWith('image/') ? 'image' : 'video';

      return {
        mediaUrl,
        mediaType,
        caption: caption.trim() || null
      };
    } catch (error) {
      console.error('Error uploading media:', error);
      alert('Error uploading media. Please try again.');
      return null;
    } finally {
      setUploading(false);
    }
  };

  // Handle send
  const handleSend = async () => {
    const mediaData = await uploadMedia();
    if (mediaData) {
      onMediaSelected(mediaData);
      onClose();
    }
  };

  // Get file type icon
  const getFileIcon = () => {
    if (!selectedFile) return <FileText size={24} />;
    if (selectedFile.type.startsWith('image/')) return <Image size={24} />;
    if (selectedFile.type.startsWith('video/')) return <Video size={24} />;
    return <FileText size={24} />;
  };

  return (
    <div className="media-upload-overlay" onClick={onClose}>
      <div className="media-upload-modal" onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className="media-upload-header">
          <h3>Send Media</h3>
          <button onClick={onClose} className="media-upload-close">
            <X size={24} />
          </button>
        </div>

        {/* File Selection / Preview */}
        <div className="media-upload-body">
          {!selectedFile ? (
            <div className="media-upload-dropzone">
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*,video/*"
                onChange={handleFileSelect}
                style={{ display: 'none' }}
              />
              <div className="media-upload-dropzone-content">
                {getFileIcon()}
                <p>Select an image or video</p>
                <button
                  className="btn-primary"
                  onClick={() => fileInputRef.current?.click()}
                >
                  Choose File
                </button>
                <small>Images: JPG, PNG, GIF • Videos: MP4, WebM</small>
                <small>Maximum size: 50MB</small>
              </div>
            </div>
          ) : (
            <div className="media-upload-preview">
              {selectedFile.type.startsWith('image/') && (
                <img src={preview} alt="Preview" className="media-preview-image" />
              )}
              {selectedFile.type.startsWith('video/') && (
                <video src={preview} controls className="media-preview-video" />
              )}
              
              <button
                className="media-upload-change"
                onClick={() => {
                  setSelectedFile(null);
                  setPreview(null);
                  setCaption('');
                }}
              >
                <X size={16} /> Remove
              </button>
            </div>
          )}
        </div>

        {/* Caption Input */}
        {selectedFile && (
          <div className="media-upload-caption">
            <input
              type="text"
              placeholder="Add caption (optional)..."
              value={caption}
              onChange={(e) => setCaption(e.target.value)}
              className="media-caption-input"
              maxLength={500}
            />
          </div>
        )}

        {/* Footer Actions */}
        {selectedFile && (
          <div className="media-upload-footer">
            <button
              className="btn-secondary"
              onClick={onClose}
              disabled={uploading}
            >
              Cancel
            </button>
            <button
              className="btn-primary"
              onClick={handleSend}
              disabled={uploading}
            >
              {uploading ? (
                <>
                  <Loader size={18} className="spinning" />
                  Sending...
                </>
              ) : (
                <>
                  <Image size={18} />
                  Send
                </>
              )}
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default MediaUpload;