import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../supabaseClient';
import {
  MessageCircle,
  Send,
  Search,
  X,
  MoreVertical,
  Plus,
  Paperclip,
  Check,
  CheckCheck,
  ArrowLeft
} from 'lucide-react';
import { getOrCreateConversation, getReceiverId } from '../../utils/conversationHelpers';
import MediaUpload from './MediaUpload';
import MediaMessage from './MediaMessage';
import { formatPrivateName } from '../../utils/nameFormatter';
import { validateMessage, getTypingWarning } from '../../utils/contentFilter';

const Messages = () => {
  const { user } = useAuth();
  const location = useLocation();
  const [loading, setLoading] = useState(true);
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [messageInput, setMessageInput] = useState('');
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [showNewConversationModal, setShowNewConversationModal] = useState(false);
  const [showMediaUpload, setShowMediaUpload] = useState(false);
  const [availableUsers, setAvailableUsers] = useState([]);
  const [userSearchTerm, setUserSearchTerm] = useState('');
  const [sending, setSending] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
  const [contentWarning, setContentWarning] = useState('');

  const messagesEndRef = useRef(null);
  const textareaRef = useRef(null);

  // Detect mobile viewport changes
  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth <= 768);
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Auto-scroll to bottom of messages
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Load conversations
  const loadConversations = useCallback(async () => {
    if (!user) return;

    try {
      const { data: conversationsDate, error: conversationsError } = await supabase
        .from('conversations')
        .select(`
          *,
          participant1:profiles!conversations_participant1_id_fkey (
            id, 
            full_name, 
            profile_photo, 
            user_type
          ),
          participant2:profiles!conversations_participant2_id_fkey (
            id, 
            full_name, 
            profile_photo, 
            user_type
          ),
          project:projects (
            id,
            title
          )
        `)
        .or(`participant1_id.eq.${user.id},participant2_id.eq.${user.id}`)
        .order('last_message_at', { ascending: false });

      if (conversationsError) throw conversationsError;

      const enrichedConversations = await Promise.all(
        (conversationsDate || []).map(async (conversation) => {
          const { data: lastMessageDate } = await supabase
            .from('messages')
            .select('content, sender_id, created_at, media_type')
            .eq('conversation_id', conversation.id)
            .order('created_at', { ascending: false })
            .limit(1)
            .single();

          const { count: unreadCount } = await supabase
            .from('messages')
            .select('*', { count: 'exact', head: true })
            .eq('conversation_id', conversation.id)
            .eq('is_read', false)
            .neq('sender_id', user.id);

          // Create preview text
          let previewText = 'No messages';
          if (lastMessageDate) {
            if (lastMessageDate.media_type === 'image') {
              previewText = '📷 Image';
            } else if (lastMessageDate.media_type === 'video') {
              previewText = '🎥 Video';
            } else if (lastMessageDate.content) {
              previewText = lastMessageDate.content;
            }
          }

          return {
            ...conversation,
            last_message_content: previewText,
            last_message_sender: lastMessageDate?.sender_id || null,
            last_message_time: lastMessageDate?.created_at || conversation.created_at,
            unread_count: unreadCount || 0
          };
        })
      );

      setConversations(enrichedConversations);
    } catch (error) {
      console.error('Error loading conversations:', error);
      setError('Error loading conversations');
    } finally {
      setLoading(false);
    }
  }, [user]);

  // Load messages for selected conversation
  const loadMessages = useCallback(async (conversationId) => {
    try {
      const { data: messagesDate, error: messagesError } = await supabase
        .from('messages')
        .select('*')
        .eq('conversation_id', conversationId)
        .order('created_at', { ascending: true });

      if (messagesError) throw messagesError;
      setMessages(messagesDate || []);
    } catch (error) {
      console.error('Error loading messages:', error);
    }
  }, []);

  // Handle selecting a conversation
  const handleSelectConversation = useCallback((conversation) => {
    setSelectedConversation(conversation);
    loadMessages(conversation.id);
    markMessagesAsRead(conversation.id);
  }, [loadMessages, markMessagesAsRead]);

  // Handle back button (mobile only)
  const handleBackToConversations = () => {
    setSelectedConversation(null);
    setMessages([]);
  };

  // Mark messages as read
  const markMessagesAsRead = useCallback(async (conversationId) => {
    try {
      const { error } = await supabase
        .from('messages')
        .update({ is_read: true })
        .eq('conversation_id', conversationId)
        .eq('is_read', false)
        .neq('sender_id', user.id);

      if (error) throw error;
      await loadConversations();
    } catch (error) {
      console.error('Error marking messages as read:', error);
    }
  }, [user?.id, loadConversations]);

  // Send message (handles both text and media)
  const handleSendMessage = async (e, mediaDate = null) => {
    e?.preventDefault();
    
    // For media messages
    if (mediaDate) {
      if (!selectedConversation || !user || sending) return;

      setSending(true);

      try {
        const receiverId = getReceiverId(selectedConversation, user.id);

        const { data: newMessage, error: messageError } = await supabase
          .from('messages')
          .insert({
            conversation_id: selectedConversation.id,
            sender_id: user.id,
            receiver_id: receiverId,
            content: mediaDate.caption,
            media_url: mediaDate.mediaUrl,
            media_type: mediaDate.mediaType,
            is_read: false
          })
          .select()
          .single();

        if (messageError) throw messageError;

        await supabase
          .from('conversations')
          .update({ last_message_at: new Date().toISOString() })
          .eq('id', selectedConversation.id);

        setMessages(prev => [...prev, newMessage]);
        await loadConversations();
      } catch (error) {
        console.error('Error sending media message:', error);
        setError('Error sending media');
        setTimeout(() => setError(''), 3000);
      } finally {
        setSending(false);
      }
      return;
    }

    // For text messages
    if (!selectedConversation || !user || !messageInput.trim() || sending) return;

    const messageContent = messageInput.trim();

    // Validate content for blocked patterns
    const validation = validateMessage(messageContent);
    if (!validation.isValid) {
      setError(validation.message);
      setContentWarning(validation.message);
      setTimeout(() => {
        setError('');
        setContentWarning('');
      }, 5000);
      return;
    }

    setSending(true);
    setMessageInput('');

    try {
      const receiverId = getReceiverId(selectedConversation, user.id);

      const { data: newMessage, error: messageError } = await supabase
        .from('messages')
        .insert({
          conversation_id: selectedConversation.id,
          sender_id: user.id,
          receiver_id: receiverId,
          content: messageContent,
          is_read: false
        })
        .select()
        .single();

      if (messageError) throw messageError;

      await supabase
        .from('conversations')
        .update({ last_message_at: new Date().toISOString() })
        .eq('id', selectedConversation.id);

      setMessages(prev => [...prev, newMessage]);
      await loadConversations();
    } catch (error) {
      console.error('Error sending message:', error);
      setError('Error sending message');
      setMessageInput(messageContent);
      setTimeout(() => setError(''), 3000);
    } finally {
      setSending(false);
    }
  };

  // Handle media selection from upload modal
  const handleMediaSelected = async (mediaDate) => {
    await handleSendMessage(null, mediaDate);
  };

  // Handle message input change with content validation
  const handleMessageInputChange = (e) => {
    const value = e.target.value;
    setMessageInput(value);

    // Real-time warning for blocked content
    const warning = getTypingWarning(value);
    setContentWarning(warning || '');
  };

  // Handle textarea input
  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage(e);
    }
  };

  // Format timestamp
  const formatMessageTime = (timestamp) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diffInSeconds = Math.floor((now - date) / 1000);

    if (diffInSeconds < 60) return 'Now';
    if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}m`;
    if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}h`;
    if (diffInSeconds < 604800) {
      const days = Math.floor(diffInSeconds / 86400);
      return days === 1 ? 'Yesterday' : `${days}d`;
    }

    return date.toLocaleDateString('en-US', { day: '2-digit', month: '2-digit' });
  };

  // Get other participant
  const getOtherParticipant = (conversation) => {
    if (!conversation) return null;
    return conversation.participant1_id === user.id 
      ? conversation.participant2 
      : conversation.participant1;
  };

  // Load available users for new conversation
  const loadAvailableUsers = async () => {
    try {
      const { data: users, error } = await supabase
        .from('profiles')
        .select('id, full_name, profile_photo, user_type')
        .neq('id', user.id)
        .order('full_name', { ascending: true });

      if (error) throw error;

      const existingUserIds = new Set();
      conversations.forEach(conv => {
        if (conv.participant1_id !== user.id) existingUserIds.add(conv.participant1_id);
        if (conv.participant2_id !== user.id) existingUserIds.add(conv.participant2_id);
      });

      setAvailableUsers(users.filter(u => !existingUserIds.has(u.id)));
    } catch (error) {
      console.error('Error loading users:', error);
    }
  };

  // Create new conversation
  const handleNewConversation = async (otherUserId) => {
    try {
      const result = await getOrCreateConversation(user.id, otherUserId, null);
      
      if (result.success) {
        await loadConversations();
        setTimeout(() => {
          const newConv = conversations.find(c => c.id === result.conversationId);
          if (newConv) handleSelectConversation(newConv);
        }, 500);
        setShowNewConversationModal(false);
      }
    } catch (error) {
      console.error('Error creating conversation:', error);
    }
  };

  // Setup real-time subscriptions
  useEffect(() => {
    if (!user) return;

    loadConversations();

    const messagesSubscription = supabase
      .channel('messages-channel')
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'messages'
      }, (payload) => {
        const newMessage = payload.new;
        if (selectedConversation && newMessage.conversation_id === selectedConversation.id) {
          setMessages(prev => {
            if (prev.some(msg => msg.id === newMessage.id)) return prev;
            return [...prev, newMessage];
          });
          if (newMessage.sender_id !== user.id) {
            markMessagesAsRead(selectedConversation.id);
          }
        }
        loadConversations();
      })
      .subscribe();

    return () => {
      messagesSubscription.unsubscribe();
    };
  }, [user, selectedConversation, loadConversations]);

  // Auto-select conversation if navigated from Browse Artists or other pages
  useEffect(() => {
    if (location.state?.conversationId && conversations.length > 0) {
      const targetConv = conversations.find(c => c.id === location.state.conversationId);
      if (targetConv) {
        handleSelectConversation(targetConv);
        // Clear the state to prevent re-selection on page refresh
        window.history.replaceState({}, document.title);
      }
    }
  }, [conversations, location.state, handleSelectConversation]);

  // Filter conversations by search
  const filteredConversations = conversations.filter(conv => {
    const otherUser = getOtherParticipant(conv);
    const displayName = formatPrivateName(otherUser?.full_name);
    return displayName.toLowerCase().includes(searchTerm.toLowerCase());
  });

  const filteredUsers = availableUsers.filter(user => {
    const displayName = formatPrivateName(user.full_name);
    return displayName.toLowerCase().includes(userSearchTerm.toLowerCase());
  });

  if (loading) {
    return (
      <div className="messages-loading">
        <div className="logo-icon">3D</div>
        <p>Loading messages...</p>
      </div>
    );
  }

  const otherParticipant = selectedConversation ? getOtherParticipant(selectedConversation) : null;

  return (
    <div className="modern-messages-container">
      {error && (
        <div className="modern-message-error">
          {error}
        </div>
      )}

      <div className="modern-messages-layout">
        {/* Sidebar - Conversation List (hide on mobile when chat is open) */}
        <div className={`modern-messages-sidebar ${isMobile && selectedConversation ? 'hidden' : ''}`}>
          {/* Sidebar Header */}
          <div className="modern-sidebar-header">
            <h2>Messages</h2>
            <button
              className="modern-new-chat-btn"
              onClick={() => {
                setShowNewConversationModal(true);
                loadAvailableUsers();
              }}
              title="New conversation"
            >
              <Plus size={20} />
            </button>
          </div>

          {/* Search Bar */}
          <div className="modern-search-container">
            <Search size={18} />
            <input
              type="text"
              placeholder="Search conversations..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="modern-search-input"
            />
            {searchTerm && (
              <button onClick={() => setSearchTerm('')} className="modern-search-clear">
                <X size={16} />
              </button>
            )}
          </div>

          {/* Conversations List */}
          <div className="modern-conversations-list">
            {filteredConversations.length === 0 ? (
              <div className="modern-empty-conversations">
                <MessageCircle size={48} />
                <p>No conversations yet</p>
                <button
                  className="btn-primary btn-sm"
                  onClick={() => {
                    setShowNewConversationModal(true);
                    loadAvailableUsers();
                  }}
                >
                  Start conversation
                </button>
              </div>
            ) : (
              filteredConversations.map(conversation => {
                const otherUser = getOtherParticipant(conversation);
                const isSelected = selectedConversation?.id === conversation.id;

                return (
                  <div
                    key={conversation.id}
                    className={`modern-conversation-item ${isSelected ? 'selected' : ''}`}
                    onClick={() => handleSelectConversation(conversation)}
                  >
                    <div className="modern-conversation-avatar">
                      {otherUser?.profile_photo ? (
                        <img src={otherUser.profile_photo} alt={formatPrivateName(otherUser.full_name)} />
                      ) : (
                        <div className="modern-avatar-placeholder">
                          {formatPrivateName(otherUser?.full_name)?.charAt(0).toUpperCase()}
                        </div>
                      )}
                    </div>

                    <div className="modern-conversation-content">
                      <div className="modern-conversation-header">
                        <span className="modern-conversation-name">
                          {formatPrivateName(otherUser?.full_name)}
                        </span>
                        <span className="modern-conversation-time">
                          {formatMessageTime(conversation.last_message_time)}
                        </span>
                      </div>

                      <div className="modern-conversation-footer">
                        <p className="modern-conversation-preview">
                          {conversation.last_message_sender === user.id && (
                            <Check size={14} className="modern-sent-indicator" />
                          )}
                          {conversation.last_message_content}
                        </p>
                        {conversation.unread_count > 0 && (
                          <span className="modern-unread-badge">
                            {conversation.unread_count}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Main Chat Area */}
        <div className="modern-chat-area">
          {selectedConversation ? (
            <>
              {/* Chat Header */}
              <div className="modern-chat-header">
                <div className="modern-chat-user-info">
                  {/* Back button for mobile */}
                  {isMobile && (
                    <button 
                      className="modern-chat-header-mobile-back"
                      onClick={handleBackToConversations}
                      title="Back"
                    >
                      <ArrowLeft size={24} />
                    </button>
                  )}
                  
                  <div className="modern-chat-avatar">
                    {otherParticipant?.profile_photo ? (
                      <img src={otherParticipant.profile_photo} alt={formatPrivateName(otherParticipant.full_name)} />
                    ) : (
                      <div className="modern-avatar-placeholder">
                        {formatPrivateName(otherParticipant?.full_name)?.charAt(0).toUpperCase()}
                      </div>
                    )}
                  </div>
                  <div className="modern-chat-user-details">
                    <h3>{formatPrivateName(otherParticipant?.full_name)}</h3>
                    <span className="modern-user-type">
                      {otherParticipant?.user_type === 'artista' ? '3D Artist' : 'Designer & Developer'}
                    </span>
                  </div>
                </div>

                <div className="modern-chat-actions">
                  <button className="modern-chat-action-btn" title="More options">
                    <MoreVertical size={20} />
                  </button>
                </div>
              </div>

              {/* Messages Area */}
              <div className="modern-messages-area">
                {messages.map((message, index) => {
                  const isOwn = message.sender_id === user.id;
                  const showAvatar = index === 0 || messages[index - 1].sender_id !== message.sender_id;
                  const showTime = index === messages.length - 1 || 
                                   messages[index + 1]?.sender_id !== message.sender_id;

                  return (
                    <div 
                      key={message.id} 
                      className={`modern-message-wrapper ${isOwn ? 'own' : 'other'}`}
                    >
                      {!isOwn && showAvatar && (
                        <div className="modern-message-avatar">
                          {otherParticipant?.profile_photo ? (
                            <img src={otherParticipant.profile_photo} alt="" />
                          ) : (
                            <div className="modern-avatar-placeholder-small">
                              {formatPrivateName(otherParticipant?.full_name)?.charAt(0).toUpperCase()}
                            </div>
                          )}
                        </div>
                      )}
                      
                      {!isOwn && !showAvatar && <div className="modern-message-avatar-spacer" />}

                      {/* Check if message has media */}
                      {message.media_url ? (
                        <MediaMessage message={message} isOwn={isOwn} />
                      ) : (
                        <div className="modern-message-bubble">
                          <div className="modern-message-content">
                            {message.content}
                          </div>
                          {showTime && (
                            <div className="modern-message-meta">
                              <span className="modern-message-time">
                                {new Date(message.created_at).toLocaleTimeString('en-US', { 
                                  hour: '2-digit', 
                                  minute: '2-digit' 
                                })}
                              </span>
                              {isOwn && (
                                <span className="modern-message-status">
                                  {message.is_read ? (
                                    <CheckCheck size={16} className="read" />
                                  ) : (
                                    <Check size={16} className="sent" />
                                  )}
                                </span>
                              )}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  );
                })}
                <div ref={messagesEndRef} />
              </div>

              {/* Input Area */}
              <div className="modern-input-area">
                {contentWarning && (
                  <div style={{
                    padding: '8px 12px',
                    background: '#fff3cd',
                    color: '#856404',
                    fontSize: '0.875rem',
                    borderRadius: '8px',
                    margin: '8px 0',
                    border: '1px solid #ffc107'
                  }}>
                    {contentWarning}
                  </div>
                )}
                <form onSubmit={handleSendMessage} className="modern-input-form">
                  {/* Attachment button */}
                  <button
                    type="button"
                    className="modern-input-action"
                    title="Attach media"
                    onClick={() => setShowMediaUpload(true)}
                    disabled={!selectedConversation}
                  >
                    <Paperclip size={20} />
                  </button>

                  <textarea
                    ref={textareaRef}
                    value={messageInput}
                    onChange={handleMessageInputChange}
                    onKeyDown={handleKeyDown}
                    placeholder="Type a message..."
                    className="modern-message-input"
                    rows={1}
                    disabled={sending}
                  />

                  <button
                    type="submit"
                    className="modern-send-button"
                    disabled={!messageInput.trim() || sending || contentWarning}
                    title="Send"
                  >
                    <Send size={20} />
                  </button>
                </form>
              </div>
            </>
          ) : (
            <div className="modern-empty-chat">
              <MessageCircle size={64} />
              <h3>Select a conversation</h3>
              <p>Choose a conversation from the sidebar or start a new one</p>
            </div>
          )}
        </div>
      </div>

      {/* New Conversation Modal */}
      {showNewConversationModal && (
        <div className="modal-overlay" onClick={() => setShowNewConversationModal(false)}>
          <div className="modal-content modern-new-chat-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>New Conversation</h3>
              <button onClick={() => setShowNewConversationModal(false)} className="modal-close">
                <X size={24} />
              </button>
            </div>

            <div className="modern-modal-search">
              <Search size={18} />
              <input
                type="text"
                placeholder="Search users..."
                value={userSearchTerm}
                onChange={(e) => setUserSearchTerm(e.target.value)}
              />
            </div>

            <div className="modern-users-list">
              {filteredUsers.length === 0 ? (
                <div className="modern-empty-users">
                  <p>No users available</p>
                </div>
              ) : (
                filteredUsers.map(otherUser => (
                  <div
                    key={otherUser.id}
                    className="modern-user-item"
                    onClick={() => handleNewConversation(otherUser.id)}
                  >
                    <div className="modern-user-avatar">
                      {otherUser.profile_photo ? (
                        <img src={otherUser.profile_photo} alt={formatPrivateName(otherUser.full_name)} />
                      ) : (
                        <div className="modern-avatar-placeholder">
                          {formatPrivateName(otherUser.full_name).charAt(0).toUpperCase()}
                        </div>
                      )}
                    </div>
                    <div className="modern-user-info">
                      <div className="modern-user-name">{formatPrivateName(otherUser.full_name)}</div>
                      <div className="modern-user-type">
                        {otherUser.user_type === 'artista' ? '3D Artist' : 'Designer & Developer'}
                      </div>
                    </div>
                    <MessageCircle size={18} className="modern-user-icon" />
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {/* Media Upload Modal */}
      {showMediaUpload && (
        <MediaUpload
          onMediaSelected={handleMediaSelected}
          onClose={() => setShowMediaUpload(false)}
        />
      )}
    </div>
  );
};

export default Messages;