import { supabase } from '../supabaseClient';

/**
 * Gets an existing conversation or creates a new one between two users
 * Uses the database function to ensure proper participant ordering and prevent duplicates
 * 
 * @param {string} userId1 - First user's ID
 * @param {string} userId2 - Second user's ID  
 * @param {string} projectId - Optional project ID to associate with conversation
 * @returns {Promise<{success: boolean, conversationId?: string, error?: string}>}
 */
export const getOrCreateConversation = async (userId1, userId2, projectId = null) => {
  try {
    // Validate inputs
    if (!userId1 || !userId2) {
      return {
        success: false,
        error: 'User IDs are required'
      };
    }

    if (userId1 === userId2) {
      return {
        success: false,
        error: 'Cannot create conversation with yourself'
      };
    }

    // Call the database function to safely create/get conversation
    const { data, error } = await supabase
      .rpc('get_or_create_conversation', {
        p_user1_id: userId1,
        p_user2_id: userId2,
        p_project_id: projectId
      });

    if (error) {
      console.error('Error in getOrCreateConversation:', error);
      return {
        success: false,
        error: 'Error creating conversation'
      };
    }

    return {
      success: true,
      conversationId: data
    };
  } catch (error) {
    console.error('Unexpected error in getOrCreateConversation:', error);
    return {
      success: false,
      error: 'Unexpected error creating conversation'
    };
  }
};

/**
 * Get the receiver ID from a conversation (the other participant)
 *
 * @param {Object} conversation - Conversation object with participant1_id and participant2_id
 * @param {string} currentUserId - Current user's ID
 * @returns {string} The other participant's ID
 */
export const getReceiverId = (conversation, currentUserId) => {
  if (!conversation) return null;
  return conversation.participant1_id === currentUserId
    ? conversation.participant2_id
    : conversation.participant1_id;
};
